'use strict';
const STAFF_INVITE_KEY='occci.staff.invitation.v1';
const STAFF_ROLES=['Admin','DM','BM','Staff','BC'];
const STAFF_ROLE_LABELS={Admin:'Admin',DM:'District Manager (DM)',BM:'Branch Manager (BM)',Staff:'Staff',BC:'Branch Cashier (BC)'};
function isOperationalStaff(){return ['Staff','BC'].includes(S.role);}
function rememberStaffInvite(){try{if(S.staffInvite?.verified)sessionStorage.setItem(STAFF_INVITE_KEY,JSON.stringify({id:S.staffInvite.id,code:S.staffInvite.code,until:Date.now()+30*60*1000}));else sessionStorage.removeItem(STAFF_INVITE_KEY);}catch{}}
function restoreStaffInvite(){let saved;try{saved=JSON.parse(sessionStorage.getItem(STAFF_INVITE_KEY)||'null');if(saved?.until<Date.now())saved=null;}catch{}const hash=new URLSearchParams(location.hash.slice(1));const id=hash.get('staff-invite')||saved?.id;if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id||''))return;S.staffInvite={id,code:saved?.id===id?saved.code:'',verified:false};}
function leaveStaffInvite(){S.staffInvite=null;S.staffInviteError='';try{sessionStorage.removeItem(STAFF_INVITE_KEY);}catch{}if(location.hash.startsWith('#staff-invite='))history.replaceState(null,'',location.pathname+location.search);S.page=isStaff()?'Overview':'Home';render();}
async function validateStaffCode(code){const i=S.staffInvite;if(!i)throw Error('Open the invitation link provided by Admin.');const valid=await api('/rest/v1/rpc/occci_verify_staff_invite',{method:'POST',auth:false,data:{invite_id:i.id,code}});if(!valid)throw Error('The link or code is invalid, expired, revoked or already used. Contact Admin for a new invitation.');i.code=code;i.verified=true;rememberStaffInvite();}
async function verifyStaffCode(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{await validateStaffCode(String(new FormData(form).get('code')||'').trim());S.staffInviteError='';render();}catch(err){const n=$('staffInviteMessage');if(n)n.textContent=err.message;}finally{btn.disabled=false;}}
async function restoreStaffCode(){if(!S.staffInvite?.code)return;try{await validateStaffCode(S.staffInvite.code);}catch(err){S.staffInvite.verified=false;S.staffInvite.code='';rememberStaffInvite();S.staffInviteError=err.message;}}
function staffInviteView(){const i=S.staffInvite;if(!i)return '';const steps=`<ol class="invite-steps" aria-label="Staff registration steps"><li class="${i.verified?'complete':'current'}">Verify code</li><li class="${i.verified&&!S.session?'current':S.session?'complete':''}">Secure sign-in</li><li class="${i.verified&&S.session?'current':''}">Employee details</li></ol>`;let body;
 if(S.session&&(isStaff()||S.applications.some(a=>a.user_id===S.session.user.id&&['Pending','Approved'].includes(a.status))||S.me?.membership_status==='Active'))body=`<h2>Account already registered</h2><p>Your account already has membership, a pending staff application or cooperative access. Admin can manage an existing assignment in CMS.</p>${button('Return to my workspace','leaveStaffInvite()','primary')}`;
 else if(!i.verified)body=`<h2>Enter your invitation code</h2><p class="smalltext">Use the separate code supplied by your cooperative Admin. Each invitation can be used once.</p><form onsubmit="event.preventDefault();verifyStaffCode(this)"><label>Special registration code<input name="code" required maxlength="80" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="XXXX-XXXX-XXXX-XXXX-XXXX-XXXX"></label><button type="submit" class="primary">Verify invitation</button><p id="staffInviteMessage" class="form-error" role="alert">${e(S.staffInviteError||'')}</p></form>`;
 else if(!S.session){const reg=S.staffAuthMode==='register';body=`<h2>Secure your account</h2><p class="smalltext">Your invitation is verified. Sign in or create an account before sending employee details.</p><button type="button" class="google-signin outline" onclick="googleSignIn(this)"><span class="google-mark" aria-hidden="true">G</span>Continue with Google</button><p class="auth-divider">or use email</p><div class="tabs">${button('Sign in',"S.staffAuthMode='login';render()",!reg?'active':'')}${button('Create sign-in',"S.staffAuthMode='register';render()",reg?'active':'')}</div><form onsubmit="event.preventDefault();submitStaffCredentials(this)"><div class="form-grid">${field('Email','email','','email')}<label>Password<input name="password" type="password" minlength="8" required autocomplete="${reg?'new-password':'current-password'}"></label></div><button type="submit" class="primary">${reg?'Create sign-in':'Sign in'}</button><p id="authMessage" role="status" aria-live="polite">${e(S.error||'')}</p></form>`;}
 else body=`<h2>Employee application</h2><p class="smalltext">Signed in as ${e(S.session.user.email)}. Admin will verify your employee ID and assign your position and workplace.</p><form onsubmit="event.preventDefault();submitStaffApplication(this)"><div class="form-grid">${field('Last name','last_name',S.me?.last_name||'')}${field('First name','first_name',S.me?.first_name||'')}${field('Middle name (optional)','middle_name',S.me?.middle_name||'','text',false)}<label>Employee Number / ID<input name="employee_id" value="${e(S.me?.employee_id||'')}" required minlength="2" maxlength="50" autocomplete="off"></label>${field('Contact number','contact_number',S.me?.contact_number||'','tel')}${avatarPicker()}<label class="full">Profile photo (optional)<input type="file" name="photo" accept="image/*"><span class="hint">Choose one of the six avatars if photo upload is unavailable on your device.</span></label></div><p class="smalltext">Submitting an application does not grant CMS access. Admin approval is required.</p><button type="submit" class="primary">Send for Admin approval</button><p id="staffInviteMessage" class="form-error" role="alert"></p></form>`;
 return heading('OCCCI employee registration','Private Admin invitation')+`<section class="card auth-card staff-invite-card">${steps}${body}<div class="invite-footer">${button('Cancel registration','leaveStaffInvite()','outline small')}${S.session?button('Use a different account','signOut()','outline small'):''}</div></section>`;
}
async function submitStaffCredentials(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{await validateStaffCode(S.staffInvite.code);const f=new FormData(form),reg=S.staffAuthMode==='register';const result=await api(reg?'/auth/v1/signup':'/auth/v1/token?grant_type=password',{method:'POST',auth:false,data:{email:String(f.get('email')||'').trim(),password:f.get('password'),...(reg?{data:{onboarding_source:'staff-invitation',registration_kind:'Member'}}:{})}});if(result.access_token){storeSession({...result,expires_at:Date.now()/1000+result.expires_in});await reload();}else{S.staffAuthMode='login';render();$('authMessage').textContent='Confirm your email, then return to this invitation link and sign in. Your application has not been sent yet.';}}catch(err){const n=$('authMessage');if(n)n.textContent=err.message;else toast(err.message);}finally{btn.disabled=false;}}
async function submitStaffApplication(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const f=new FormData(form),values_json=Object.fromEntries(['last_name','first_name','middle_name','employee_id','contact_number','avatar'].map(k=>[k,String(f.get(k)||'').trim()]));await rpc('occci_submit_staff_application',{invite_id:S.staffInvite.id,code:S.staffInvite.code,values_json});const file=f.get('photo');leaveStaffInvite();await reload();let message='Application sent. Your Admin will review it and assign your position.';if(file?.size){try{await uploadPhotoBlob(await normalizePhoto(file));}catch(err){message+=' Your selected avatar is saved. '+err.message;}}toast(message);}catch(err){const n=$('staffInviteMessage');if(n)n.textContent=err.message;else toast(err.message);}finally{btn.disabled=false;}}
function staffInviteLink(id){return location.origin+'/#staff-invite='+encodeURIComponent(id);}
function staffInviteStatus(i){return i.redeemed_at?'Used':i.revoked_at?'Revoked':Date.parse(i.expires_at)<=Date.now()?'Expired':'Active';}
async function loadStaffInvites(){S.staffInvites=[];S.staffInvitesError='';if(S.role!=='Admin')return;try{S.staffInvites=await allRows('/rest/v1/occci_staff_invites?select=id,label,created_by,created_at,expires_at,revoked_at,redeemed_at,redeemed_by&order=created_at.desc,id');}catch(err){S.staffInvitesError=err.message;}}
function staffSettingsView(){if(S.role!=='Admin')return empty('Admin settings','Only Admin can manage employee invitations.');return heading('Admin settings','Invite employees privately and assign their roles after review.',button('Generate staff invitation','staffInviteDialog()','primary small','plus'))+`<section class="card reports-panel"><div class="card-head"><h2>Staff registration invitations</h2><span class="smalltext">${S.staffInvites.length} invitations</span></div><p class="smalltext">Share the link and code separately with the intended employee. Codes are shown once when generated. Each link accepts one application; unused invitations can be revoked.</p>${S.staffInvitesError?`<p class="form-error" role="alert">${e(S.staffInvitesError)}</p>`:''}<ul class="request-list">${S.staffInvites.map(i=>`<li class="request-list-row"><div class="request-list-info"><div class="request-list-title"><h2>${e(i.label)}</h2>${statusPill(staffInviteStatus(i))}</div><p class="request-list-meta">Created ${e(new Date(i.created_at).toLocaleDateString())} · Expires ${e(new Date(i.expires_at).toLocaleString())}${i.redeemed_by?' · '+e(S.profiles.find(p=>p.id===i.redeemed_by)?.full_name||'Employee applied'):''}</p></div><div class="flex">${staffInviteStatus(i)==='Active'?button('Copy link',`copyStaffLink('${i.id}',this)`,'outline small')+button('Revoke',`revokeStaffInviteDialog('${i.id}')`,'outline small'):''}</div></li>`).join('')}</ul>${S.staffInvites.length?'':empty('No employee invitations','Generate a link and separate code to invite an OCCCI employee.')}</section>`;}
function staffInviteDialog(){if(S.role!=='Admin')return;openModal('Generate staff invitation',`<form onsubmit="event.preventDefault();createStaffInvite(this)"><div class="form-grid"><label class="full">Invitation label<input name="label" maxlength="150" placeholder="Employee name or internal reference" required></label><label>Valid for<select name="valid_days">${[1,3,7,14,30].map(d=>`<option value="${d}" ${d===7?'selected':''}>${d} day${d===1?'':'s'}</option>`).join('')}</select></label><label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="5000" required rows="2"></textarea></label></div><p class="hint">The employee cannot choose a position. You assign Admin, DM, BM, Staff or BC when approving the application.</p><button type="submit" class="primary">Generate link and code</button></form>`);}
async function createStaffInvite(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const f=new FormData(form),i=await rpc('occci_create_staff_invite',{label:String(f.get('label')||'').trim(),valid_days:Number(f.get('valid_days')),reason:f.get('reason')});await loadStaffInvites();render();openModal('Staff invitation generated',`<p class="smalltext">Copy both items now. The code will not be displayed again after this dialog closes. Share it separately with the employee.</p><label>Private registration link<input id="generatedStaffLink" readonly value="${e(staffInviteLink(i.id))}"></label>${button('Copy link',"copyStaffValue('generatedStaffLink',this)",'outline small')}<label>Special registration code<input id="generatedStaffCode" readonly value="${e(i.code)}" autocomplete="off"></label>${button('Copy code',"copyStaffValue('generatedStaffCode',this)",'outline small')}<p class="hint">One application · Expires ${e(new Date(i.expires_at).toLocaleString())}</p>${button('Done','closeModal()','primary')}`);const secret=$('generatedStaffCode');$('modal').addEventListener('close',()=>{secret.value='';},{once:true});}catch(err){$('actionMessage').textContent=err.message;}finally{btn.disabled=false;}}
async function copyStaffValue(id,btn){await copyStaffText($(id).value,btn);}
async function copyStaffLink(id,btn){await copyStaffText(staffInviteLink(id),btn);}
async function copyStaffText(value,btn){try{await navigator.clipboard.writeText(value);if(btn){const original=btn.textContent;btn.textContent='Copied';setTimeout(()=>{btn.textContent=original;},1800);}}catch{toast('Copy is unavailable. Select the displayed link or code and copy it manually.');}}
function revokeStaffInviteDialog(id){openModal('Revoke staff invitation',`<form onsubmit="event.preventDefault();revokeStaffInvite(this,'${id}')"><p class="smalltext">This unused link and code will stop accepting applications.</p><label>Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="5000" required></textarea></label><button type="submit" class="primary">Revoke invitation</button></form>`);}
async function revokeStaffInvite(form,id){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{await rpc('occci_revoke_staff_invite',{invite_id:id,reason:new FormData(form).get('reason')});closeModal();await reload();toast('Invitation revoked and recorded.');}catch(err){$('actionMessage').textContent=err.message;}finally{btn.disabled=false;}}
function staffReviewDecisionChanged(){const form=$('modalContent').querySelector('form'),approve=form.elements.decision.value==='Approve';$('staffAssignmentFields').hidden=!approve;form.elements.employee_id.required=approve;form.elements.employee_id.disabled=!approve;form.elements.role.disabled=!approve;if(approve)teamRoleChanged();else{form.elements.district.disabled=true;form.elements.branch_id.disabled=true;}}
async function staffApplicantPhoto(id){const p=S.profiles.find(p=>p.id===id);if(!p?.photo_path)return;try{const url=await signedUrl('occci-avatars',p.photo_path),n=$('staffApplicantAvatar');if(n&&n.dataset.user===id)n.innerHTML=`<img src="${e(url)}" alt="Applicant profile photo">`;}catch{}}
